(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.015-t*0.22)*18 + Math.sin(x*0.013+t*0.28)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.02+t*0.4)*10 + Math.cos(my*0.025-t*0.3)*8;
  const w2y = Math.cos(my*0.02-t*0.35)*10 + Math.sin(mx*0.022+t*0.45)*8;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.8],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 5.5],
    [400+Math.cos(t*0.38+2)*60, 220+Math.sin(t*0.72)*40, 0.085, 1.8, 2.0]
  ];
  let aS=0, iS=0, hrm=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp + ph);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + ph + 1.5);
    hrm += Math.sin(d*f*1.3 - t*sp*0.4 + ph*2.0)*0.6;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, harm = hrm/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.5+Math.sin(sx*0.12-sy*0.08+t*2)*0.25)/2.75;
  const micro = (Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin((sx+sy)*0.2+t*2)*Math.sin((sx-sy)*0.15-t*1.8))*0.15;
  const dist1 = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang1 = Math.atan2(sy-cy, sx-cx);
  const c2x = 200+Math.sin(t*0.3)*60, c2y = 100+Math.cos(t*0.25)*40;
