  const raw = act - inh*0.65 + bg*0.25 + spirals + harm*0.4 + micro;
  const reaction = Math.tanh(raw*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-t*0.5)*Math.cos(sy*0.12+t*0.3)*0.3)*1.5)*0.25;
  const dx = Math.sin((sx+1)*0.15)*Math.sin(sy*0.15)-Math.sin((sx-1)*0.15)*Math.sin(sy*0.15);
  const dy = Math.sin(sx*0.15)*Math.sin((sy+1)*0.15)-Math.sin(sx*0.15)*Math.sin((sy-1)*0.15);
  const edgeGlow = Math.sqrt(dx*dx+dy*dy)*2.5;
  const v = (reaction*0.7+cell*0.2+edgeGlow*0.1)*0.5+0.5;
  const pal = [[5,12,52],[12,45,88],[18,88,118],[28,145,132],[68,178,118],[182,192,68],[232,178,48],[222,118,55],[192,68,58],[138,38,68],[82,22,72],[38,14,58],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const pulse = 0.85+Math.sin(t*0.8)*0.05+Math.sin(reaction*Math.PI)*0.1;
  const lum = pulse*(Math.abs(reaction)>0.65?1.12+edgeGlow*0.5:1.0);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
